SELECT p.gender, p.age, a.admittime, a.dischtime, a.deathtime, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, emar.medication, COUNT(DISTINCT emar.drug) AS drug_count, percent_rank() OVER (ORDER BY COUNT(DISTINCT emar.drug)) AS percentile_rank, MIN(s.los) AS min_los, AVG(s.los) AS avg_los, MAX(s.los) AS max_los, SUM(CASE WHEN p.deathtime IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(COUNT(a.hadm_id), 0) AS mortality_rate, COUNT(a.hadm_id) / 30.0 AS readmission_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id LEFT JOIN emar ON a.hadm_id = emar.hadm_id AND a.subject_id = emar.subject_id WHERE p.gender = 'F' AND p.age BETWEEN 76 AND 86 AND a.dischtime - a.admittime <= 7 AND (emar.medication IS NOT NULL AND emar.medication != '') GROUP BY p.gender, p.age, a.admittime, a.dischtime, a.deathtime, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, emar.medication ORDER BY percentile_rank NULLS LAST;